#include <iostream>

double kmToMiles(double km)
{
    return km * 0.621371;
}

double kgToPounds(double kg)
{
    return kg * 2.20462;
}

int main()
{
    double km{};
    double kg{};
    std::cin >> km >> kg;
    std::cout << kmToMiles(km) << " miles\n";
    std::cout << kgToPounds(kg) << " pounds\n";
    return 0;
}

